import CryptoKit
import Foundation
import Testing

@testable import MoqomMLS

/// Writes the Swift-generated files in `vectors/mls`. Run with
/// `MOQOM_MLS_GENERATE=1 swift test --filter MLSVectorGenerator`.
///
/// Inputs that the caller chooses (secrets, contexts, labels) are fixed, so
/// `mls-key-schedule.json` and the KDF cases regenerate byte for byte. CryptoKit
/// takes no caller randomness for ML-KEM encapsulation or ML-DSA signing, so
/// every file with a ciphertext or signature in it is a recorded transcript:
/// regenerating changes those bytes and everything that depends on them, and
/// is only for when the format changes.
@Suite("Vector generator", .enabled(if: ProcessInfo.processInfo.environment["MOQOM_MLS_GENERATE"] == "1"))
struct MLSVectorGenerator {
    private let suite = MLSCipherSuite.mls256MLKEM1024MLDSA87
    private let source = "Generated by MoqomMLS (Swift, CryptoKit): Tests/MoqomMLSTests/VectorGenerator.swift"

    /// Bytes fixed by a name, so generated inputs do not change.
    private func fixed(_ name: String, _ count: Int) -> Data {
        var out = Data()
        var block: UInt8 = 0
        while out.count < count {
            out += Data(SHA512.hash(data: Data("moqom-mls \(name)".utf8) + Data([block])))
            block += 1
        }
        return out.prefix(count)
    }

    private func flipped(_ data: Data, at offset: Int) -> Data {
        var copy = data
        let index = offset >= 0 ? copy.startIndex + offset : copy.endIndex + offset
        copy[index] ^= 0x01
        return copy
    }

    @Test("crypto")
    func crypto() throws {
        var cases: [[String: Any]] = []
        let secret = fixed("secret", 64)
        let context = fixed("context", 64)
        cases.append([
            "name": "expand-with-label", "op": "expand_with_label",
            "secret_hex": secret.hex, "label": "ExpandWithLabel", "context_hex": context.hex, "length": 32,
            "out_hex": try suite.expandWithLabel(secret, label: "ExpandWithLabel", context: context, length: 32).hex,
        ])
        cases.append([
            "name": "derive-secret", "op": "derive_secret", "secret_hex": secret.hex, "label": "DeriveSecret",
            "out_hex": suite.deriveSecret(secret, label: "DeriveSecret").hex,
        ])
        cases.append([
            "name": "ref-hash", "op": "ref_hash", "label": "MLS 1.0 KeyPackage Reference", "value_hex": context.hex,
            "out_hex": suite.refHash(label: "MLS 1.0 KeyPackage Reference", value: context).hex,
        ])

        let signingSeed = fixed("signature seed", 32)
        let signing = try MLDSA87.PrivateKey(seedRepresentation: signingSeed, publicKey: nil)
        let content = fixed("content", 64)
        let signature = try suite.signWithLabel(signingSeed, label: "FramedContentTBS", content: content)
        let signed: [String: Any] = [
            "op": "sign_with_label", "seed_hex": signingSeed.hex, "public_key_hex": signing.publicKey.rawRepresentation.hex,
            "label": "FramedContentTBS", "content_hex": content.hex, "signature_hex": signature.hex,
        ]
        cases.append(signed.merging(["name": "sign-with-label"]) { $1 })
        cases.append(signed.merging(["name": "sign-with-label-other-label", "label": "GroupInfoTBS", "error": "bad-signature"]) { $1 })
        cases.append(signed.merging(["name": "sign-with-label-tampered", "signature_hex": flipped(signature, at: 100).hex, "error": "bad-signature"]) { $1 })
        cases.append(signed.merging(["name": "sign-with-label-other-content", "content_hex": flipped(content, at: 0).hex, "error": "bad-signature"]) { $1 })

        let kemSeed = fixed("kem seed", 64)
        let kem = try MLKEM1024.PrivateKey(seedRepresentation: kemSeed, publicKey: nil)
        let plaintext = fixed("plaintext", 64)
        let sealed = try suite.encryptWithLabel(kem.publicKey.rawRepresentation, label: "UpdatePathNode", context: context, plaintext: plaintext)
        let encrypted: [String: Any] = [
            "op": "encrypt_with_label", "seed_hex": kemSeed.hex, "public_key_hex": kem.publicKey.rawRepresentation.hex,
            "label": "UpdatePathNode", "context_hex": context.hex, "plaintext_hex": plaintext.hex,
            "kem_output_hex": sealed.kemOutput.hex, "ciphertext_hex": sealed.ciphertext.hex,
        ]
        cases.append(encrypted.merging(["name": "encrypt-with-label"]) { $1 })
        cases.append(encrypted.merging(["name": "encrypt-with-label-other-label", "label": "Welcome", "error": "decryption-failed"]) { $1 })
        cases.append(encrypted.merging(["name": "encrypt-with-label-other-context", "context_hex": flipped(context, at: 0).hex, "error": "decryption-failed"]) { $1 })
        cases.append(encrypted.merging(["name": "encrypt-with-label-tampered", "ciphertext_hex": flipped(sealed.ciphertext, at: 0).hex, "error": "decryption-failed"]) { $1 })
        cases.append(encrypted.merging(["name": "encrypt-with-label-short-kem-output", "kem_output_hex": sealed.kemOutput.dropLast().hex, "error": "decryption-failed"]) { $1 })

        try Vectors.write(
            "mls-crypto.json",
            description: "RFC 9420 §5 labelled primitives in MLS_256_MLKEM1024_AES256GCM_SHA512_MLDSA87 (0xF0AC): ExpandWithLabel, DeriveSecret and RefHash over HKDF-SHA512; SignWithLabel over ML-DSA-87 (pure, empty context); EncryptWithLabel over HPKE KEM 0x0042 (ML-KEM-1024), KDF 0x0003 (HKDF-SHA512), AES-256-GCM. Seeds are FIPS 203 (d || z) and FIPS 204 (xi). Signatures and ciphertexts are to verify and open, not to reproduce.",
            source: source, cases: cases
        )
    }

    @Test("key schedule")
    func keySchedule() throws {
        let groupID = fixed("group", 16)
        var initSecret = fixed("initial init secret", 64)
        var epochs: [[String: Any]] = []
        var confirmed = Data()
        for epoch in 0 ..< 4 {
            let commitSecret = fixed("commit secret \(epoch)", 64)
            let context = MLSGroupContext(
                cipherSuite: suite, groupID: groupID, epoch: UInt64(epoch),
                treeHash: fixed("tree hash \(epoch)", 64), confirmedTranscriptHash: confirmed
            )
            let secrets = MLSEpochSecrets.derive(initSecret: initSecret, commitSecret: commitSecret, context: context)
            let exporters: [[String: Any]] = try [
                ("SFrame 1.0 Base Key", Data(), 32), ("SFrame 1.0 Base Key", Data(), 16),
                ("MOQOM direct offer", Data(), 32), ("label", fixed("exporter context", 20), 64),
            ].map { label, context, length in
                ["label": label, "context_hex": context.hex, "length": length,
                 "out_hex": try secrets.exporter(label: label, context: context, length: length).hex]
            }
            epochs.append([
                "commit_secret_hex": commitSecret.hex,
                "tree_hash_hex": context.treeHash.hex,
                "confirmed_transcript_hash_hex": confirmed.hex,
                "group_context_hex": context.encoded.hex,
                "joiner_secret_hex": secrets.joinerSecret.hex,
                "welcome_secret_hex": secrets.welcomeSecret.hex,
                "epoch_secret_hex": secrets.epochSecret.hex,
                "sender_data_secret_hex": secrets.senderDataSecret.hex,
                "encryption_secret_hex": secrets.encryptionSecret.hex,
                "exporter_secret_hex": secrets.exporterSecret.hex,
                "external_secret_hex": secrets.externalSecret.hex,
                "confirmation_key_hex": secrets.confirmationKey.hex,
                "membership_key_hex": secrets.membershipKey.hex,
                "resumption_psk_hex": secrets.resumptionPSK.hex,
                "epoch_authenticator_hex": secrets.epochAuthenticator.hex,
                "init_secret_hex": secrets.initSecret.hex,
                "exporters": exporters,
            ])
            initSecret = secrets.initSecret
            confirmed = fixed("confirmed transcript hash \(epoch + 1)", 64)
        }
        try Vectors.write(
            "mls-key-schedule.json",
            description: "RFC 9420 §8 key schedule in suite 0xF0AC over four chained epochs: the GroupContext encoding (no extensions), every epoch secret, the next init secret, and MLS-Exporter, including the RFC 9605 §5.2 SFrame base key. PSK secret is the all-zero default.",
            source: source,
            cases: [["name": "suite-f0ac", "cipher_suite": Int(suite.identifier), "group_id_hex": groupID.hex,
                     "initial_init_secret_hex": fixed("initial init secret", 64).hex, "epochs": epochs]]
        )
    }

    private func signedPackage(
        _ suite: MLSCipherSuite, identity: String, signingKey: Data, signatureKey: Data, initKey: Data, encryptionKey: Data
    ) throws -> Data {
        let unsigned = MLSKeyPackage(
            cipherSuite: suite, identity: Data(identity.utf8), signatureKey: signatureKey,
            initKey: initKey, encryptionKey: encryptionKey, signature: Data()
        )
        let signature = try suite.signWithLabel(signingKey, label: "KeyPackageTBS", content: unsigned.toBeSigned)
        return unsigned.toBeSigned + {
            var w = MLSWriter()
            w.vector(signature)
            return w.bytes
        }()
    }

    @Test("key packages")
    func keyPackages() throws {
        var cases: [[String: Any]] = []
        func valid(_ name: String, _ bundle: MLSKeyPackageBundle) {
            let package = bundle.keyPackage
            cases.append([
                "name": name, "key_package_hex": package.encoded.hex,
                "expect": [
                    "cipher_suite": Int(package.cipherSuite.identifier), "identity": package.identityString,
                    "signature_key_hex": package.signatureKey.hex, "init_key_hex": package.initKey.hex,
                    "encryption_key_hex": package.encryptionKey.hex, "reference_hex": package.reference.hex,
                ] as [String: Any],
            ])
        }
        let bob = try MLSKeyPackageBundle.generate(identity: "bob/b")
        valid("valid-f0ac", bob)

        let encoded = bob.keyPackage.encoded
        func failing(_ name: String, _ data: Data, _ error: String) {
            cases.append(["name": name, "key_package_hex": data.hex, "error": error])
        }
        failing("bad-signature", flipped(encoded, at: -1), "bad-signature")
        failing("identity-changed", {
            var data = encoded
            data[data.startIndex + 5] = UInt8(ascii: "c")
            return data
        }(), "bad-signature")
        // The AES-128 suites are refused as unknown, never parsed as a weaker group.
        var relabelledX25519 = encoded
        relabelledX25519[relabelledX25519.startIndex + 2] = 0x00
        relabelledX25519[relabelledX25519.startIndex + 3] = 0x01
        failing("aes128-suite-0001", relabelledX25519, "unsupported")
        var relabelledXWing = encoded
        relabelledXWing[relabelledXWing.startIndex + 3] = 0xA1
        failing("aes128-suite-f0a1", relabelledXWing, "unsupported")
        var relabelledMLKEM768 = encoded
        relabelledMLKEM768[relabelledMLKEM768.startIndex + 3] = 0xAA
        failing("ml-kem-768-suite-f0aa", relabelledMLKEM768, "unsupported")
        var relabelledMLDSA65 = encoded
        relabelledMLDSA65[relabelledMLDSA65.startIndex + 3] = 0xAB
        failing("ml-dsa-65-suite-f0ab", relabelledMLDSA65, "unsupported")
        var unknownSuite = encoded
        unknownSuite[unknownSuite.startIndex + 2] = 0x00
        unknownSuite[unknownSuite.startIndex + 3] = 0x02
        failing("unknown-suite", unknownSuite, "unsupported")
        var unknownVersion = encoded
        unknownVersion[unknownVersion.startIndex + 1] = 0x02
        failing("unknown-version", unknownVersion, "unsupported")
        failing("trailing-byte", encoded + Data([0]), "malformed")
        failing("truncated", encoded.dropLast(), "malformed")

        let p = bob.keyPackage
        failing("init-key-is-encryption-key", try signedPackage(
            suite, identity: "bob/b", signingKey: bob.signaturePrivate, signatureKey: p.signatureKey,
            initKey: p.encryptionKey, encryptionKey: p.encryptionKey
        ), "invalid-key-package")
        failing("init-key-not-ml-kem", try signedPackage(
            suite, identity: "bob/b", signingKey: bob.signaturePrivate, signatureKey: p.signatureKey,
            initKey: Data(repeating: 0xFF, count: 1568), encryptionKey: p.encryptionKey
        ), "invalid-key-package")
        failing("init-key-short", try signedPackage(
            suite, identity: "bob/b", signingKey: bob.signaturePrivate, signatureKey: p.signatureKey,
            initKey: p.initKey.dropLast(), encryptionKey: p.encryptionKey
        ), "invalid-key-package")
        let ed25519 = Curve25519.Signing.PrivateKey()
        let edUnsigned = MLSKeyPackage(
            cipherSuite: suite, identity: Data("bob/b".utf8), signatureKey: ed25519.publicKey.rawRepresentation,
            initKey: p.initKey, encryptionKey: p.encryptionKey, signature: Data()
        )
        var signContent = MLSWriter()
        signContent.vector(Data("MLS 1.0 KeyPackageTBS".utf8))
        signContent.vector(edUnsigned.toBeSigned)
        var edSignature = MLSWriter()
        edSignature.vector(try ed25519.signature(for: signContent.bytes))
        failing("ed25519-key-in-ml-dsa-suite", edUnsigned.toBeSigned + edSignature.bytes, "invalid-key-package")

        try Vectors.write(
            "mls-key-packages.json",
            description: "Key package decode and verify in MLS_256_MLKEM1024_AES256GCM_SHA512_MLDSA87 (0xF0AC), the only suite; the AES-128 suites 0x0001 and 0xF0A1 and MOQOM's earlier suites 0xF0AA and 0xF0AB are refused as unsupported. Checks version, suite, identity, ML-DSA-87 signature key, init and encryption keys, signature over KeyPackageTBS, and KeyPackageRef. Failing cases have exactly one defect each.",
            source: source, cases: cases
        )
    }

    private func state(_ group: MLSGroup) throws -> [String: Any] {
        [
            "epoch": Int(group.epoch),
            "own_leaf": Int(group.ownLeaf),
            "members": group.members.leaves.map { $0.map { $0.identityString as Any } ?? NSNull() },
            "epoch_authenticator_hex": group.epochAuthenticator.hex,
            "exporters": try [
                ("SFrame 1.0 Base Key", Data(), 32), ("MOQOM direct offer", Data(), 32),
            ].map { label, context, length in
                ["label": label, "context_hex": context.hex, "length": length,
                 "out_hex": try group.exporter(label: label, context: context, length: length).hex] as [String: Any]
            },
        ]
    }

    private func member(_ bundle: MLSKeyPackageBundle) -> [String: Any] {
        [
            "key_package_hex": bundle.keyPackage.encoded.hex,
            "init_private_hex": bundle.initPrivate.hex,
            "encryption_private_hex": bundle.encryptionPrivate.hex,
            "signature_private_hex": bundle.signaturePrivate.hex,
        ]
    }

    private func advanced(_ outcome: MLSCommitOutcome) throws -> MLSGroup {
        guard case let .advanced(next) = outcome else { throw MLSError.notAddressed }
        return next
    }

    private func reframed(_ m: MLSCommitMessage, groupID: Data? = nil, signature: Data? = nil) -> Data {
        MLSCommitMessage(
            groupID: groupID ?? m.groupID, epoch: m.epoch, sender: m.sender, commit: m.commit,
            signature: signature ?? m.signature, confirmationTag: m.confirmationTag
        ).encoded
    }

    @Test("group")
    func group() throws {
        let groupID = Data("acme/room-42".utf8)
        let aliceBundle = try MLSKeyPackageBundle.generate(identity: "alice/a")
        let bob = try MLSKeyPackageBundle.generate(identity: "bob/b")
        let carol = try MLSKeyPackageBundle.generate(identity: "carol/c")
        let dave = try MLSKeyPackageBundle.generate(identity: "dave/d")
        let stranger = try MLSKeyPackageBundle.generate(identity: "bob/b")

        var bobSteps: [[String: Any]] = []
        var daveSteps: [[String: Any]] = []

        var alice = try MLSGroup.create(groupID: groupID, bundle: aliceBundle)
        let addBob = try alice.commit(adding: [bob.keyPackage])
        alice = addBob.next
        var bobGroup = try MLSGroup.join(try #require(addBob.welcome), bundle: bob)
        bobSteps.append(["welcome_hex": try #require(addBob.welcome).encoded.hex, "expect": try state(bobGroup)])

        let addTwo = try alice.commit(adding: [carol.keyPackage, dave.keyPackage])
        alice = addTwo.next
        bobGroup = try advanced(try bobGroup.process(addTwo.message))
        bobSteps.append(["commit_hex": addTwo.message.encoded.hex, "expect": try state(bobGroup)])
        var carolGroup = try MLSGroup.join(try #require(addTwo.welcome), bundle: carol)
        var daveGroup = try MLSGroup.join(try #require(addTwo.welcome), bundle: dave)
        daveSteps.append(["welcome_hex": try #require(addTwo.welcome).encoded.hex, "expect": try state(daveGroup)])

        // Carol rotates her leaf: an empty commit from a member who did not found.
        let update = try carolGroup.commit()
        carolGroup = update.next
        alice = try advanced(try alice.process(update.message))
        bobGroup = try advanced(try bobGroup.process(update.message))
        daveGroup = try advanced(try daveGroup.process(update.message))
        bobSteps.append(["commit_hex": update.message.encoded.hex, "expect": try state(bobGroup)])
        daveSteps.append(["commit_hex": update.message.encoded.hex, "expect": try state(daveGroup)])

        // Refused, each leaving the follower where it was.
        let rotate = try alice.commit()
        for (name, data, error) in [
            ("forged-signature", reframed(rotate.message, signature: flipped(rotate.message.signature, at: 10)), "bad-signature"),
            ("forged-confirmation-tag", flipped(rotate.message.encoded, at: -1), "confirmation-mismatch"),
            ("other-group", reframed(rotate.message, groupID: Data("acme/room-43".utf8)), "wrong-group"),
            ("replayed", update.message.encoded, "wrong-epoch"),
            ("truncated", rotate.message.encoded.dropLast(), "malformed"),
        ] {
            bobSteps.append(["name": name, "commit_hex": data.hex, "error": error])
            daveSteps.append(["name": name, "commit_hex": data.hex, "error": error])
        }
        alice = rotate.next
        carolGroup = try advanced(try carolGroup.process(rotate.message))
        bobGroup = try advanced(try bobGroup.process(rotate.message))
        daveGroup = try advanced(try daveGroup.process(rotate.message))
        bobSteps.append(["commit_hex": rotate.message.encoded.hex, "expect": try state(bobGroup)])
        daveSteps.append(["commit_hex": rotate.message.encoded.hex, "expect": try state(daveGroup)])

        // Alice removes Dave; Dave is told.
        let removeDave = try alice.commit(removing: [try #require(alice.leaf(of: "dave/d"))])
        alice = removeDave.next
        carolGroup = try advanced(try carolGroup.process(removeDave.message))
        bobGroup = try advanced(try bobGroup.process(removeDave.message))
        guard case .removed = try daveGroup.process(removeDave.message) else { throw MLSError.invalidProposal }
        bobSteps.append(["commit_hex": removeDave.message.encoded.hex, "expect": try state(bobGroup)])
        daveSteps.append(["commit_hex": removeDave.message.encoded.hex, "removed": true])

        // Carol removes Alice, the founder, and re-adds Dave in the blank leaf.
        let dave2 = try MLSKeyPackageBundle.generate(identity: "dave/d")
        let reshape = try carolGroup.commit(adding: [dave2.keyPackage], removing: [try #require(carolGroup.leaf(of: "alice/a"))])
        carolGroup = reshape.next
        bobGroup = try advanced(try bobGroup.process(reshape.message))
        bobSteps.append(["commit_hex": reshape.message.encoded.hex, "expect": try state(bobGroup)])

        // Carol removes Bob.
        let removeBob = try carolGroup.commit(removing: [try #require(carolGroup.leaf(of: "bob/b"))])
        guard case .removed = try bobGroup.process(removeBob.message) else { throw MLSError.invalidProposal }
        bobSteps.append(["commit_hex": removeBob.message.encoded.hex, "removed": true])

        let welcome = try #require(addBob.welcome)
        var info = welcome.encoded
        info[info.endIndex - 1] ^= 1
        try Vectors.write(
            "mls-group.json",
            description: "Group transcripts in suite 0xF0AC made by Swift, followed by one member whose private keys are given: join by Welcome, then process each commit in order (adds, an Update from a non-founder, removes, the founder removed, the follower removed). After each step the follower's epoch, leaf, member list (null for a blank leaf), epoch authenticator and exporters must match. A step with \"error\" must fail with that class and leave the follower unchanged; one with \"removed\" must report the follower removed.",
            source: source,
            cases: [
                ["name": "bob-follows", "cipher_suite": Int(suite.identifier), "group_id_hex": groupID.hex, "member": member(bob), "steps": bobSteps],
                ["name": "dave-joins-two-at-once", "cipher_suite": Int(suite.identifier), "group_id_hex": groupID.hex, "member": member(dave), "steps": daveSteps],
                ["name": "welcome-for-another-package", "cipher_suite": Int(suite.identifier), "group_id_hex": groupID.hex, "member": member(stranger),
                 "steps": [["welcome_hex": welcome.encoded.hex, "error": "not-addressed"]]],
                ["name": "welcome-tampered", "cipher_suite": Int(suite.identifier), "group_id_hex": groupID.hex, "member": member(bob),
                 "steps": [["welcome_hex": info.hex, "error": "decryption-failed"]]],
            ]
        )
    }

    @Test("audience")
    func audience() throws {
        let seed = fixed("viewer seed", 64)
        let viewer = try MLKEM1024.PrivateKey(seedRepresentation: seed, publicKey: nil)
        let groupID = fixed("audience group", 16)
        let base = fixed("base key", 32)
        let envelope = try MLSAudience.seal(base, to: viewer.publicKey.rawRepresentation, groupID: groupID, epoch: 7)
        let sealed: [String: Any] = [
            "private_key_hex": seed.hex, "public_key_hex": viewer.publicKey.rawRepresentation.hex,
            "group_id_hex": groupID.hex, "epoch": 7, "envelope_hex": envelope.hex,
        ]
        let cases: [[String: Any]] = [
            sealed.merging(["name": "open", "base_key_hex": base.hex]) { $1 },
            sealed.merging(["name": "other-epoch", "epoch": 8, "error": "decryption-failed"]) { $1 },
            sealed.merging(["name": "other-group", "group_id_hex": flipped(groupID, at: 0).hex, "error": "decryption-failed"]) { $1 },
            sealed.merging(["name": "tampered", "envelope_hex": flipped(envelope, at: -1).hex, "error": "decryption-failed"]) { $1 },
            sealed.merging(["name": "trailing-byte", "envelope_hex": (envelope + Data([0])).hex, "error": "malformed"]) { $1 },
            sealed.merging(["name": "truncated", "envelope_hex": envelope.dropLast().hex, "error": "malformed"]) { $1 },
        ]
        try Vectors.write(
            "mls-audience.json",
            description: "Sender keys for viewers: an epoch's SFrame base key sealed with EncryptWithLabel(pk, \"MOQOM audience key\", vector(group_id) || uint64(epoch), base_key) in suite 0xF0AC, the envelope being the HPKECiphertext's encoding. The viewer's key is a 64-byte ML-KEM-1024 seed.",
            source: source, cases: cases
        )
    }
}
